  ;(function () {
    var params = new URLSearchParams(window.location.search)
    var host = window.location.hostname
    var isLocal = host === 'localhost' || host === '127.0.0.1' || host === '::1' || host === '[::1]'
    var shellOff = params.get('nx_device') === 'off'
    var shellOn = params.get('nx_device') === 'iphone16pm'
    var isInner = params.get('nx_device_inner') === '1'
    var shouldUseShell = !isInner && !shellOff && (isLocal || shellOn)

    if (!shouldUseShell) {
      return
    }

    window.__NX_DEVICE_SHELL__ = true
    document.documentElement.classList.add('nx-device-host')
    document.documentElement.setAttribute('data-nx-app-theme', 'dark')
    var innerUrl = new URL(window.location.href)
    innerUrl.searchParams.set('nx_device_inner', '1')
    var safeSrc = innerUrl.href.replace(/&/g, '&amp;').replace(/"/g, '&quot;')

    document.write(
      '<div class="nx-device-stage">' +
        '<div class="nx-device-fit">' +
          '<div class="nx-phone-preview">' +
            '<div class="nx-phone-screen">' +
              '<iframe id="nx-app-frame" src="' + safeSrc + '" title="UVEL app preview"></iframe>' +
            '</div>' +
          '</div>' +
        '</div>' +
      '</div>',
    )

    function fitDevice() {
      var outerW = 472
      var outerH = 988
      var padding = window.innerWidth <= 520 ? 20 : 36
      var scale = Math.min(
        1,
        Math.max(0.36, (window.innerWidth - padding) / outerW),
        Math.max(0.36, (window.innerHeight - padding) / outerH),
      )
      document.documentElement.style.setProperty('--nx-device-scale', String(scale))
      document.documentElement.style.setProperty('--nx-device-fit-w', outerW * scale + 'px')
      document.documentElement.style.setProperty('--nx-device-fit-h', outerH * scale + 'px')
    }

    var lastHostHash = window.location.hash

    function syncFrameFromHost() {
      var frame = document.getElementById('nx-app-frame')
      if (!frame || !frame.contentWindow) return
      try {
        lastHostHash = window.location.hash
        if (frame.contentWindow.location.hash !== window.location.hash) {
          frame.contentWindow.location.hash = window.location.hash
        }
      } catch {}
    }

    function syncHostFromFrame() {
      var frame = document.getElementById('nx-app-frame')
      if (!frame || !frame.contentWindow) return
      try {
        var frameHash = frame.contentWindow.location.hash
        if (frameHash && frameHash !== window.location.hash) {
          history.replaceState(null, '', window.location.pathname + window.location.search + frameHash)
          lastHostHash = frameHash
        }
      } catch {}
    }

    function syncThemeFromFrame() {
      var frame = document.getElementById('nx-app-frame')
      if (!frame || !frame.contentDocument) return
      try {
        var mode = frame.contentDocument.documentElement.getAttribute('data-theme')
        document.documentElement.setAttribute('data-nx-app-theme', mode === 'light' ? 'light' : 'dark')
      } catch {}
    }

    function syncRouteDrift() {
      syncThemeFromFrame()
      if (window.location.hash !== lastHostHash) {
        syncFrameFromHost()
        return
      }
      syncHostFromFrame()
    }

    function bindFrameRouteSync() {
      var frame = document.getElementById('nx-app-frame')
      if (!frame) return
      frame.addEventListener('load', function () {
        syncFrameFromHost()
        syncThemeFromFrame()
        try {
          frame.contentWindow.addEventListener('hashchange', syncHostFromFrame)
        } catch {}
      })
      window.addEventListener('hashchange', syncFrameFromHost)
      syncFrameFromHost()
      window.setInterval(syncRouteDrift, 500)
    }

    fitDevice()
    bindFrameRouteSync()
    window.addEventListener('resize', fitDevice)
  })()

